import{_ as a,o,c as p,a2 as d}from"./chunks/framework.Bg-Zxr5O.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/DATA-LIST-FIXED.md","filePath":"manual-zh/DATA-LIST-FIXED.md","lastUpdated":1785684581000}'),c={name:"manual-zh/DATA-LIST-FIXED.md"};function t(T,e,r,A,n,I){return o(),p("div",null,[...e[0]||(e[0]=[d(`<h4 id="_8-5-1-data-list-fixed" tabindex="-1">8.5.1 DATA LIST FIXED <a class="header-anchor" href="#_8-5-1-data-list-fixed" aria-label="Permalink to &quot;8.5.1 DATA LIST FIXED&quot;">​</a></h4><pre><code>DATA LIST [FIXED]
        {TABLE,NOTABLE}
        [FILE=’file_name’ [ENCODING=’encoding’]]
        [RECORDS=record_count]
        [END=end_var]
        [SKIP=record_count]
        /[line_no] var_spec…

where each var_spec takes one of the forms
        var_list start-end [type_spec]
        var_list (fortran_spec)
</code></pre><p><code>DATA LIST FIXED</code> 用于读取在单行或多行记录的每一行上具有固定位置的值的数据文件。关键字 FIXED 是可选的。</p><p>如果要从外部文件获取输入，则必须使用 <code>FILE</code> 子命令。它可用于以字符串形式指定文件名或文件句柄（参见 <a href="./File-Handles">文件句柄</a>）。如果未使用 <code>FILE</code> 子命令，则假定输入是通过 <code>BEGIN DATA</code>…<code>END DATA</code>（参见 <a href="./BEGIN-DATA">BEGIN DATA</a>）在命令文件内指定的。<code>ENCODING</code> 子命令仅在与 <code>FILE</code> 子命令同时使用时才能使用。它指定文件的字符编码。有关支持的编码信息，参见 <a href="./INSERT">INSERT</a>。</p><p>可选的 <code>RECORDS</code> 子命令以单个整数作为参数，用于指定每个记录的行数。如果未指定 <code>RECORDS</code>，则每个记录的行数由 <code>DATA LIST</code> 后面列出的变量说明计算而得。</p><p><code>END</code> 子命令仅在与 <code>INPUT PROGRAM</code> 配合使用时才有用。详见 <a href="./INPUT-PROGRAM">INPUT PROGRAM</a>。</p><p>可选的 <code>SKIP</code> 子命令指定在输入文件开头要跳过的记录数。例如，它可用于跳过包含变量名的一行。</p><p><code>DATA LIST</code> 可选择输出一个描述数据文件如何被读取的表。<code>TABLE</code> 子命令启用此输出，<code>NOTABLE</code> 禁用它。默认是输出该表。</p><p>要从数据列表中读取的变量列表必须放在最后。数据记录中的每一行以一个斜杠（‘/’）开头。可选地，行号可以跟在斜杠之后。随后可以出现任意数量的变量说明。</p><p>每个变量说明由一个变量名列表后接它们在输入行上位置的说明组成。可以使用 <code>DATA LIST</code> 的 <code>TO</code> 约定来指定变量集合（参见 <a href="./Sets-of-Variables">变量集合</a>）。有两种方式可以指定变量在行上的位置：列式（columnar）和 FORTRAN 式。</p><p>在列式中，字段的起始列和结束列在变量名之后以短横线（‘-’）分隔指定。例如，行上的第 3 到第 5 列应指定为‘3-5’。默认情况下，变量被视为‘F’格式（参见 <a href="./Input-and-Output-Formats">输入与输出格式</a>）。（此默认可更改；更多信息见 <a href="./SET">SET</a>。）</p><p>在列式中，若要使用默认之外的变量格式，可在列号之后以括号指定格式类型。例如，对于字母数字‘A’格式，使用‘(A)’。</p><p>此外，可在列号之后的括号中指定隐含小数位。例如，假设某数据文件有一个字段，其中字符‘1234’应被解释为具有值 12.34。那么该字段有两个隐含小数位，相应的说明将是‘(2)’。如果带有隐含小数位的字段包含小数点，则不应用隐含小数位。</p><p>更改变量格式与添加隐含小数位可以一起进行；例如‘(N,5)’。</p><p>使用列式时，每个变量的输入和输出宽度由字段宽度计算得出。字段宽度必须能被所指定的变量个数整除。</p><p>FORTRAN 式是一种完全不同的指定字段位置的方法。使用这种方法时，变量输入格式说明的列表（以逗号分隔）被放在变量名之后的括号内。每个格式说明符会沿输入行推进它所使用的字符数那么多位置。</p><p>FORTRAN 式中也存在隐含小数位。带有 d 个小数位的格式说明也带有 d 个隐含小数位。</p><p>除标准格式说明符（参见 <a href="./Input-and-Output-Formats">输入与输出格式</a>）外，FORTRAN 式还定义了一些扩展：</p><p><code>X</code></p><p>将本行当前列向前推进一个字符位置。</p><p><code>T</code>x</p><p>将本行当前列设置为第 x 列，列号被认为从左边距的 1 开始计数。</p><p><code>NEWREC</code>x</p><p>在当前记录中向前跳过 x 行，并将活动列重置到左边距。</p><p>重复计数</p><p>任何格式说明符之前都可加一个数字。这会导致该格式说明符的动作重复指定次数。</p><p>(spec1, …, specN)</p><p>将给定说明符分组在一起。这在前面带有重复计数时最为有用。分组可以任意嵌套。</p><p>FORTRAN 式和列式可以自由混用。列式将活动列留在所指定结束列的正后方。FORTRAN 式中使用 <code>NEWREC</code> 的记录移动也适用于后续的 FORTRAN 和列式说明符。</p><table tabindex="0"><thead><tr><th>• DATA LIST FIXED Examples</th><th></th><th>DATA LIST FIXED 的示例。</th></tr></thead></table>`,30)])])}const D=a(c,[["render",t]]);export{s as __pageData,D as default};
